insert into public.reviews (id, user_id, restaurant_id, dish_id, dish_name, body, bucket, score, cleanliness, spent, photo_urls, verified, is_demo, created_at) values
('df85752b-655a-5d69-8d58-849cb61918a7','2a85cc01-10b6-5594-adf2-dbb7588ab43d','b7822e7d-faea-5c47-9212-7d86136f42c9',(select id from public.dishes where slug='kacchi'),'Kacchi biryani','Meat falls off the bone and the aloo is soaked in ghee. Go before 1pm or it sells out. ৳380 for a full plate is a steal.','loved',9.7,4,420,array['https://images.unsplash.com/photo-1589302168068-964664d93dc0?w=900&q=70&auto=format&fit=crop'],true,true,'2026-10-09T17:58:00+00:00'),
('b4752f8f-bc9b-55a9-aa83-16b6fa056d02','26636708-2593-5ed8-a802-c4b09da3a7f7','b7822e7d-faea-5c47-9212-7d86136f42c9',(select id from public.dishes where slug='kacchi'),'Kacchi biryani','Still the benchmark for Old Dhaka kacchi. Seating is tight and hot, but nobody comes here for the chairs.','loved',9.4,3,400,array['https://images.unsplash.com/photo-1633945274405-b6c8069047b0?w=900&q=70&auto=format&fit=crop'],true,true,'2026-10-17T14:54:00+00:00'),
('74d0e116-226f-5ef1-8308-5dbb319144f1','9e3992ae-c89e-5c68-a04e-13cc108af0c9','b7822e7d-faea-5c47-9212-7d86136f42c9',(select id from public.dishes where slug='kacchi'),'Kacchi biryani','Took friends from Chattogram here and they went quiet for ten minutes. That says enough.','loved',9.0,3,380,'{}',false,true,'2026-10-06T12:25:00+00:00'),
('538fa125-f6a6-5fba-82e3-c2f60300f926','bc9d52cb-d168-59e4-99a8-28e267ba738a','b7822e7d-faea-5c47-9212-7d86136f42c9',(select id from public.dishes where slug='kacchi'),'Kacchi biryani','Great rice, slightly less meat than last time. Borhani is excellent.','loved',8.6,3,450,array['https://images.unsplash.com/photo-1563379091339-03b21ab4a4f8?w=900&q=70&auto=format&fit=crop'],false,true,'2026-09-24T20:41:00+00:00'),
('4d67bafc-46fb-5804-a74c-ab2b3620f412','d4fc1356-ae34-5cca-90f7-1a5150560547','32a7f741-08f9-51eb-a00c-0474f39522ef',(select id from public.dishes where slug='steak'),'Steak','Crisp duck skin, perfect lentils, and the best service in Gulshan right now. Book on weekends.','loved',8.9,5,3200,array['https://images.unsplash.com/photo-1600891964092-4316c288032e?w=900&q=70&auto=format&fit=crop'],true,true,'2026-10-22T06:56:00+00:00'),
('4a04e5bb-7089-5a2e-b31d-070c19cbc605','916d0957-5a3e-58ca-afc9-771341bc94d7','32a7f741-08f9-51eb-a00c-0474f39522ef',(select id from public.dishes where slug='cake'),'Chocolate cake','Dessert menu is better than the mains. Beautiful room for a birthday dinner.','loved',8.2,5,2400,array['https://images.unsplash.com/photo-1768260732302-12822bd6427b?w=900&q=70&auto=format&fit=crop'],false,true,'2026-10-21T04:33:00+00:00'),
('037d8c07-8d4c-5067-822f-eeb34db906be','80210692-7a0e-570e-9de5-e08fcbbfa581','32a7f741-08f9-51eb-a00c-0474f39522ef',null,'Mixed order','Very polished, but the portions are small for the price. Good for a special night, not a regular.','loved',7.4,5,3000,'{}',true,true,'2026-09-17T02:37:00+00:00'),
('7034e095-f7ee-55ff-aaf7-a38b2b881d5b','80210692-7a0e-570e-9de5-e08fcbbfa581','17bf8857-cc0c-5717-b6f8-d007ec9b3f6c',(select id from public.dishes where slug='mezbani'),'Mezbani beef','Closest thing to a real Chattogram mezban in Dhaka. Proper black-pepper heat. Ask for extra kala bhuna gravy.','loved',9.3,3,600,array['https://images.unsplash.com/photo-1654863404432-cac67587e25d?w=900&q=70&auto=format&fit=crop'],true,true,'2026-09-30T02:21:00+00:00'),
('60bbb099-c491-53d6-a921-5fbe6b32934f','26636708-2593-5ed8-a802-c4b09da3a7f7','17bf8857-cc0c-5717-b6f8-d007ec9b3f6c',(select id from public.dishes where slug='mezbani'),'Mezbani beef','Under ৳600 for a meal this good. Lunch rush is chaos, go at 3pm.','loved',9.0,3,550,'{}',true,true,'2026-10-20T04:52:00+00:00'),
('a82e87a5-075c-55fd-9741-e4cc91bafdff','6586ab91-ac77-5f67-aed0-a9fe625bf2fb','17bf8857-cc0c-5717-b6f8-d007ec9b3f6c',(select id from public.dishes where slug='bhorta'),'Bhorta & bhaat','Their shutki bhorta is the real thing. Rice was a bit overcooked.','loved',8.4,4,500,array['https://images.unsplash.com/photo-1588644525273-f37b60d78512?w=900&q=70&auto=format&fit=crop'],false,true,'2026-10-07T20:15:00+00:00'),
('e5cb902d-068b-575c-aab4-4065c7ff9817','26636708-2593-5ed8-a802-c4b09da3a7f7','4bfbfe06-f764-5e3f-8bca-92121776896f',(select id from public.dishes where slug='tehari'),'Beef tehari','Morning tehari with a cold borhani. Simple, cheap, consistent.','loved',8.1,3,250,array['https://images.unsplash.com/photo-1631515243349-e0cb75fb8d3a?w=900&q=70&auto=format&fit=crop'],true,true,'2026-09-27T23:07:00+00:00'),
('e073838d-ff3b-5147-920d-2704a4f85968','9e3992ae-c89e-5c68-a04e-13cc108af0c9','4bfbfe06-f764-5e3f-8bca-92121776896f',(select id from public.dishes where slug='tehari'),'Beef tehari','Tasty but the place needs a deep clean. Takeaway is the move.','loved',7.6,2,280,'{}',false,true,'2026-10-21T20:19:00+00:00'),
('382312c2-ad7c-5046-a593-1855c27a8b3b','80210692-7a0e-570e-9de5-e08fcbbfa581','38d9b9c2-640d-56fd-8439-f1cc01898377',(select id from public.dishes where slug='ilish'),'Shorshe ilish','Mustard is sharp the way it should be, fish was fresh. Portion is small for the price.','loved',8.6,4,1400,array['https://images.unsplash.com/photo-1626508035297-0cd27c397d67?w=900&q=70&auto=format&fit=crop'],true,true,'2026-10-01T09:25:00+00:00'),
('f90ddeb1-73cb-59b0-aca8-9586db53c45a','6586ab91-ac77-5f67-aed0-a9fe625bf2fb','38d9b9c2-640d-56fd-8439-f1cc01898377',(select id from public.dishes where slug='ilish'),'Shorshe ilish','Close to home cooking. Their bhapa ilish is better than the fried one.','loved',8.0,4,1200,array['https://images.unsplash.com/photo-1620894580123-466ad3a0ca06?w=900&q=70&auto=format&fit=crop'],false,true,'2026-10-14T17:10:00+00:00'),
('cd021182-eef2-5b10-9bb8-5949280e2fc0','26636708-2593-5ed8-a802-c4b09da3a7f7','a2983e60-931b-5147-8d8e-5eee0db2cd62',null,'Mixed order','Malai cha is great, the singara was cold. Worth it for the tea and the lake breeze.','loved',7.2,3,120,array['https://images.unsplash.com/photo-1544787219-7f47ccb76574?w=900&q=70&auto=format&fit=crop'],false,true,'2026-10-22T18:43:00+00:00'),
('d7e327b5-9e82-553a-badb-23b9cc45e2a6','9e3992ae-c89e-5c68-a04e-13cc108af0c9','a2983e60-931b-5147-8d8e-5eee0db2cd62',null,'Mixed order','Good tea, too crowded in the evening.','fine',6.4,2,150,'{}',false,true,'2026-10-20T13:48:00+00:00'),
('1077b231-7b38-532c-b7f0-436e7ce219c0','bc9d52cb-d168-59e4-99a8-28e267ba738a','64f68fb3-8b49-50e7-b4df-07eae1065721',(select id from public.dishes where slug='kebab'),'Kebab platter','Chicken tikka is juicy and the naan comes out blistered. Generous platter.','loved',8.3,4,850,array['https://images.unsplash.com/photo-1771285119318-b342c3ecc51c?w=900&q=70&auto=format&fit=crop'],false,true,'2026-10-04T18:01:00+00:00'),
('a9492686-8b07-5f02-8b60-efb4841639c1','80210692-7a0e-570e-9de5-e08fcbbfa581','64f68fb3-8b49-50e7-b4df-07eae1065721',(select id from public.dishes where slug='kebab'),'Kebab platter','Solid grill, slightly heavy on the food colouring. Seekh kebab is the pick.','loved',7.8,4,900,array['https://images.unsplash.com/photo-1555939594-58d7cb561ad1?w=900&q=70&auto=format&fit=crop'],true,true,'2026-10-05T10:55:00+00:00'),
('70fc98fb-eecc-57a3-a4b8-db6de54bc30b','9e3992ae-c89e-5c68-a04e-13cc108af0c9','991eaf6d-490e-5b56-879c-21eeafe35630',(select id from public.dishes where slug='momo'),'Momo','Pan-fried momo with a proper crisp bottom. The chilli sauce is dangerous.','loved',8.8,4,450,array['https://images.unsplash.com/photo-1694923450868-b432a8ee52aa?w=900&q=70&auto=format&fit=crop'],false,true,'2026-10-21T07:22:00+00:00'),
('0389477b-e381-5b1d-8117-3e97804d7336','916d0957-5a3e-58ca-afc9-771341bc94d7','991eaf6d-490e-5b56-879c-21eeafe35630',(select id from public.dishes where slug='momo'),'Momo','Steamed ones are soft and juicy. Great for a quick bite after college.','loved',8.2,4,500,array['https://images.unsplash.com/photo-1784550368264-0228aacbf50d?w=900&q=70&auto=format&fit=crop'],false,true,'2026-10-13T12:48:00+00:00'),
('db34d910-71ca-5bfa-91fd-d29e87b188ff','2a85cc01-10b6-5594-adf2-dbb7588ab43d','2724d1d3-b2a0-55f0-9e78-39a767b44e43',(select id from public.dishes where slug='kebab'),'Kebab platter','Shami kebab that melts. The nehari on Fridays is worth the trip to Old Dhaka.','loved',9.1,3,650,array['https://images.unsplash.com/photo-1777891258069-454e66f8bedc?w=900&q=70&auto=format&fit=crop'],true,true,'2026-10-20T08:36:00+00:00'),
('eafecee2-bdd4-5f42-a862-129c512b117e','26636708-2593-5ed8-a802-c4b09da3a7f7','2724d1d3-b2a0-55f0-9e78-39a767b44e43',(select id from public.dishes where slug='haleem'),'Haleem','Thick, slow-cooked haleem with proper bone marrow. Cheap and filling.','loved',8.7,3,350,array['https://images.unsplash.com/photo-1512010151537-2cf5c638ad51?w=900&q=70&auto=format&fit=crop'],true,true,'2026-09-29T09:47:00+00:00'),
('b87a348a-8a8e-537b-9c1e-f50c1fd5d85a','d4fc1356-ae34-5cca-90f7-1a5150560547','b8c85d81-1c97-5e32-a167-39b952f9303e',(select id from public.dishes where slug='steak'),'Steak','Ribeye was cooked exactly medium-rare. Pricey, but this is the best steak I''ve had in Dhaka.','loved',8.8,5,3800,array['https://images.unsplash.com/photo-1588168333986-5078d3ae3976?w=900&q=70&auto=format&fit=crop'],true,true,'2026-10-05T03:59:00+00:00'),
('3a55501a-e50f-510b-972b-afd1825347c5','bc9d52cb-d168-59e4-99a8-28e267ba738a','b8c85d81-1c97-5e32-a167-39b952f9303e',(select id from public.dishes where slug='steak'),'Steak','Excellent meat, sides are forgettable. Save it for a celebration.','loved',8.1,5,3500,'{}',false,true,'2026-10-21T19:07:00+00:00'),
